    13	export class BillingService {
    14	    private static readonly logger = new Logger(BillingService.name);
    15	    constructor(
    16	        readonly InfluxService: InfluxService,
    17	        @Inject(forwardRef(() => ServicesService)) readonly servicesService: ServicesService,
    18	        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService
    19	    ) {}
    20	    @Process({ name: billingScheduleConsumers.billingReport })
    21	    async create({ data: { scheduleParameters } }: Job<SchedulerEntity>) {
    22	        const { customerId, businessID } = scheduleParameters as CreateBillingReportDto;
    23	        // 1. Called via the scheduler contains a customerId, and BusinessID, gets set when a customer is created
    24	        // 2, Get all services for the customer
    25	        const { data } = await this.servicesService.findAllServicesWithCustomerId({ customerId, businessID });
    26	        if (data.length) {
    27	            const lineItems = await Billing.generateLineItemsFromServices({
    28	                data,
    29	                influxService: this.InfluxService,
    30	                businessID,
    31	            });
    32	            BillingService.logger.log(`Line Items for billing: ${JSON.stringify(lineItems)}`);
    33	            // 5. Create the Invoice by calling the invoice module and passing the line items (Might need to manually call the email in the invioceModule look into this )
    34	            const { invoiceId } = await this.invoicesService.create({ businessID, customerId, items: lineItems });
    35	            // Should set Invoice to Draft status, actual payment will be handled by the payment module and is done when there is a state change with the invoice status.
    36	            const { startTime, endTime } = Billing.billingCycleToTimeRange(data[0]?.offering.billingCycle);
    37	            const entity = new Billing({
    38	                invoiceId,
    39	                businessID,
    40	                customerId,
    41	                startTime,
    42	                endTime,
    43	                billingId: randomUUID(),
    44	            });
    45	            // 6. Save Billing information to the Ledger
    46	            const point = Billing.transformer(entity, this.InfluxService);
    47	            await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'enterprise', [point]);
    48	        } else {
    49	            BillingService.logger.log(`No Billing Data found for customer:${customerId} in business: ${businessID}`);
    50	        }
    51	    }
    52	}
