    24	    constructor({ invoiceId, businessID, customerId, startTime, endTime, billingId }: Billing) {
    25	        this.invoiceId = invoiceId;
    26	        this.businessID = businessID;
    27	        this.customerId = customerId;
    28	        this.startTime = startTime;
    29	        this.endTime = endTime;
