    33	    public static async generateLineItemsFromServices({
    34	        data,
    35	        influxService,
    36	        businessID,
    37	    }: {
    38	        data: ReadServiceResponseData[];
    39	        influxService: InfluxService;
    40	        businessID: string;
    41	    }): Promise<InvoiceLineItem[]> {
    42	        const dimensionMap = data.reduce((acc, item): { [key: string]: ReadDimensionResponseData } => {
    43	            const { dimensions } = item.offering;
    44	            dimensions.forEach(({ dimensionId, ...rest }) => {
    45	                acc[dimensionId] = { ...rest, dimensionId, offering: { ...item.offering } };
    46	            });
    47	            return acc;
    48	        }, {});
    49	        // 4. Map dimensions to line items, read the aggregation information for the past billing cycle (group by customerId) from the DB and create a line item
    50	        const lineItems = await Promise.all(
    51	            Object.keys(dimensionMap).map(async (dimensionId) => {
    52	                const {
    53	                    dimensionName,
    54	                    consumptionPrice,
    55	                    consumptionUnit: { unit },
    56	                    offering: { offeringName, billingCycle },
    57	                } = dimensionMap[dimensionId];
    58	                const invoiceName = Billing.invoiceNameGenerator({ dimensionName, offeringName, dimensionUnit: unit });
    59	                const { startTime, endTime } = Billing.billingCycleToTimeRange(billingCycle);
    60	                const totalUsage = await influxService.readAggregateUsage({
    61	                    dimensionId,
    62	                    startTime,
    63	                    endTime,
    64	                    businessID,
    65	                });
    66	                const accumulatedUsage = totalUsage.reduce((acc, { _value }): number => {
    67	                    acc += _value;
    68	                    return acc;
    69	                }, 0);
    70	                return new InvoiceLineItem(invoiceName, accumulatedUsage, consumptionPrice);
    71	            })
    72	        );
    73	        return lineItems;
    74	    }
    75	
    76	    public static billingCycleToTimeRange(billingCycle: validBillingCycles): { startTime: string; endTime: string } {
    77	        if (billingCycle === 'monthly') {
    78	            const date = new Date();
    79	            const firstDay = new Date(date.getFullYear(), date.getMonth() - 1, 1);
    80	            const lastDay = new Date(date.getFullYear(), date.getMonth(), 0);
    81	            return { startTime: firstDay.toISOString(), endTime: lastDay.toISOString() };
    82	        }
    83	    }
    84	    private static invoiceNameGenerator({
    85	        offeringName,
    86	        dimensionName,
    87	        dimensionUnit,
    88	    }: {
    89	        offeringName: string;
    90	        dimensionName: string;
    91	        dimensionUnit: string;
    92	    }) {
    93	        return `${dimensionName} (${offeringName}) - ${dimensionUnit}`;
    94	    }
