    96	    public static transformer(billingEntity: Billing, influxService: InfluxService) {
    97	        const billingEntityPoint = influxService.getPoint(Billing._measurement);
    98	
    99	        billingEntityPoint.stringField('billingId', billingEntity.billingId);
   100	        billingEntityPoint.tag('billingId', billingEntity.billingId);
   101	        billingEntityPoint.tag('invoiceId', billingEntity.invoiceId);
   102	        billingEntityPoint.tag('businessID', billingEntity.businessID);
   103	        billingEntityPoint.tag('customerId', billingEntity.customerId);
   104	        billingEntityPoint.tag('startTime', billingEntity.startTime);
   105	        billingEntityPoint.tag('endTime', billingEntity.endTime);
   106	
   107	        return billingEntityPoint;
   108	    }
   109	
   110	    public static dbModelToEntity(dbModel) {
   111	        return new Billing({
   112	            invoiceId: dbModel.invoiceId,
   113	            businessID: dbModel.businessID,
   114	            customerId: dbModel.customerId,
   115	            startTime: dbModel.startTime,
   116	            endTime: dbModel.endTime,
   117	            billingId: dbModel.billingId,
   118	        });
   119	    }
   120	
   121	    public static usageToTotal(aggregatedUsageResponse: AggregatedUsageResponse): string {
   122	        try {
   123	            const { usage } = aggregatedUsageResponse;
   124	
   125	            // TODO take into account discounts and other factors
   126	            const totalUsage = usage.reduce((acc, { value }) => {
   127	                acc += parseFloat(value);
   128	                return acc;
   129	            }, 0);
   130	            return totalUsage.toString();
   131	        } catch (e) {
   132	            AuditService.publishEvent({ message: 'error in usageToTotal', data: [e], topic: AuditScope.ERROR });
   133	        }
   134	    }
   135	}
