114	    static transformer(customerEntity: CustomerEntity, influxService: InfluxService): Array<Point> {
115	        const customerEntityPoint = influxService.getPoint(CustomerEntity._measurement);
116	
117	        customerEntityPoint.tag('customerId', customerEntity.customerId);
118	        customerEntityPoint.tag('businessID', customerEntity.businessID);
119	        customerEntityPoint.tag('paymentChannel', customerEntity.paymentChannel);
120	        customerEntityPoint.tag('customerVatId', customerEntity.customerVatId);
121	        customerEntityPoint.tag('taxExempt', customerEntity.taxExempt);
122	        customerEntityPoint.tag('email', customerEntity.email);
123	        customerEntityPoint.stringField('customerName', customerEntity.customerName);
124	        if (customerEntity.address) {
125	            customerEntityPoint.tag('address', JSON.stringify(customerEntity.address));
126	        }
127	        if (customerEntity.offeringId) {
128	            customerEntityPoint.tag('offeringId', customerEntity.offeringId);
129	        }
130	        if (customerEntity.paymentChannelOptions) {
131	            Object.keys(customerEntity.paymentChannelOptions).forEach((key) => {
132	                customerEntityPoint.tag(`paymentChannelOptions_${key}`, customerEntity.paymentChannelOptions[key]);
133	            });
134	        }
135	        if (customerEntity.softDelete) {
136	            customerEntityPoint.tag('softDelete', 'deleted');
137	        }
138	        // All Entity Transformers should return an array of points, keep logic consistent, even if there is only one element
139	        return [customerEntityPoint];
140	    }
