142	    static dbModelToEntity(dbModel) {
143	        const { _value, customerId, paymentChannel, email, address, customerVatId, taxExempt, offeringId, ...rest } =
144	            dbModel;
145	
146	        const paymentChannelOptions = Object.keys(rest)
147	            .filter((key) => /paymentChannelOptions_/.test(key))
148	            .reduce((acc, key) => {
149	                acc[key.split('paymentChannelOptions_')[1]] = rest[key];
150	                return acc;
151	            }, {}) as CustomerEntity['paymentChannelOptions'];
152	        return new CustomerEntity({
153	            email,
154	            customerName: _value,
155	            customerId,
156	            paymentChannel,
157	            paymentChannelOptions,
158	            address: address ? JSON.parse(address) : {},
159	            customerVatId,
160	            taxExempt,
161	            offeringId,
162	        });
163	    }
