import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { CustomerService } from './customer.service';
import { InfluxService } from '../influx/influx.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { ServicesService } from '../services/services.service';
import { OfferingService } from '../offering/offering.service';
import { UsageService } from '../usage/usage.service';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from '../scheduler/dto/scheduler.dto';
import { CustomerEntity } from './entities/customer.entity';
import { paymentChannel } from './dto/create-customer.dto';

describe('CustomerService', () => {
    const businessID = 'myCoolCorp';
    const offeringId = 'bc546e8a-3a2c-4089-8133-1efac1759ff5';
    const subject = 'auth0|1234';

    let service: CustomerService;
    const mockLoadPoints = jest.fn();
    const mockSchedulerCreate = jest.fn();
    const mockSchedulerRemove = jest.fn();
    const mockFindUsageForCustomer = jest.fn();
    let mockGetLatestCustomer: jest.Mock;

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        mockGetLatestCustomer = jest.fn(() => []);
        jest.spyOn(CustomerEntity, 'transformer').mockImplementation(() => []);
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getLatestCustomer: (...args) => mockGetLatestCustomer(...args),
                        getInvoicesForCustomer: jest.fn(() => []),
                        getPoint: () => ({ tag: jest.fn(), stringField: jest.fn() }),
                    };
                }
                if (token === SchedulerService) {
                    return { create: mockSchedulerCreate, remove: mockSchedulerRemove };
                }
                if (token === OfferingService) {
                    return { findOne: jest.fn(() => ({ data: [{ offeringId }], message: 'Found Offering' })) };
                }
                if (token === ServicesService) {
                    return {};
                }
                if (token === UsageService) {
                    return { findUsageForCustomer: mockFindUsageForCustomer };
                }
            })
            .compile();

        service = module.get<CustomerService>(CustomerService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    describe('create', () => {
        const createCustomerDto = {
            businessID,
            customerName: 'Wall Street Trading',
            email: 'test@enterprise.tech',
            paymentChannel: paymentChannel.Stripe,
        };

        it('creates a monthly billing schedule when the customer has an offering', async () => {
            const { customerId } = await service.create({ ...createCustomerDto, offeringId }, subject);

            expect(mockSchedulerCreate).toHaveBeenCalledTimes(1);
            expect(mockSchedulerCreate).toHaveBeenCalledWith({
                schedulerID: customerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: { customerId, businessID },
                rate: SupportedMeasurementFrequencies.monthly,
                subject,
                businessID,
            });
        });

        it('does not create a billing schedule when the customer has no offering', async () => {
            await service.create(createCustomerDto, subject);

            expect(mockLoadPoints).toHaveBeenCalledTimes(1);
            expect(mockSchedulerCreate).not.toHaveBeenCalled();
        });
    });

    describe('update', () => {
        const customerId = 'b9459f53-054b-4437-8ecd-b6f8070344fc';
        const customerDbModel = {
            _value: 'Wall Street Trading',
            customerId,
            businessID,
            email: 'test@enterprise.tech',
            paymentChannel: paymentChannel.Stripe,
        };

        it('replaces the billing schedule when a customer gains an offering', async () => {
            mockGetLatestCustomer.mockImplementation(() => [customerDbModel]);

            await service.update({ customerId, businessID, offeringId }, subject);

            expect(mockSchedulerRemove).toHaveBeenCalledWith({
                schedulerID: customerId,
                businessID,
                isBillingQueue: true,
            });
            expect(mockSchedulerCreate).toHaveBeenCalledWith({
                schedulerID: customerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: { customerId, businessID },
                rate: SupportedMeasurementFrequencies.monthly,
                subject,
                businessID,
            });
        });

        it('creates the customer level schedule even when no previous schedule exists', async () => {
            mockGetLatestCustomer.mockImplementation(() => [customerDbModel]);
            mockSchedulerRemove.mockRejectedValueOnce(new NotFoundException('Schedule not found'));

            await expect(service.update({ customerId, businessID, offeringId }, subject)).resolves.toEqual({
                message: 'Customer updated added',
                customerId,
            });
            expect(mockSchedulerCreate).toHaveBeenCalledTimes(1);
        });

        it('leaves the billing schedule alone when the offering does not change', async () => {
            mockGetLatestCustomer.mockImplementation(() => [{ ...customerDbModel, offeringId }]);

            await service.update({ customerId, businessID, offeringId, customerName: 'renamed' }, subject);

            expect(mockSchedulerRemove).not.toHaveBeenCalled();
            expect(mockSchedulerCreate).not.toHaveBeenCalled();
        });
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { Job } from 'bull';
import { BillingService } from './billing.service';
import { InfluxService } from '../influx/influx.service';
import { InvoicesService } from '../invoice/invoices.service';
import { CustomerService } from '../customer/customer.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';
import { Billing } from './entities/billing.entity';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from '../scheduler/dto/scheduler.dto';
import { validBillingCycles } from '../offering/dto/createOffering.dto';

describe('BillingService', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'b9459f53-054b-4437-8ecd-b6f8070344fc';
    const invoiceId = '0f1eb5d0-1cb5-4b3f-a2ae-fb00d2f0d3d5';

    let service: BillingService;
    const mockLoadPoints = jest.fn();
    const mockGenerateInvoiceForUsageTotal = jest.fn(() => ({ invoiceId, message: 'Generated invoice' }));
    let mockCustomerFindOne: jest.Mock;

    const job = {
        data: new SchedulerEntity({
            schedulerID: customerId,
            schedulerStatus: SchedulerStatus.live,
            schedulerType: schedulerType.billing,
            scheduleParameters: { customerId, businessID },
            rate: SupportedMeasurementFrequencies.monthly,
            businessID,
            subject: 'auth0|1234',
        }),
    } as Job<SchedulerEntity>;

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        mockCustomerFindOne = jest.fn(() => ({
            data: [{ customerId, offeringId: 'offer-1', offering: { billingCycle: validBillingCycles.monthly } }],
            message: 'Found Customer',
        }));
        const module: TestingModule = await Test.createTestingModule({
            providers: [BillingService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag: jest.fn(), stringField: jest.fn() }),
                    };
                }
                if (token === CustomerService) {
                    return { findOne: (...args) => mockCustomerFindOne(...args) };
                }
                if (token === InvoicesService) {
                    return { generateInvoiceForUsageTotal: mockGenerateInvoiceForUsageTotal };
                }
            })
            .compile();

        service = module.get<BillingService>(BillingService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('invoices the customer for the offering billing cycle and stores the billing record', async () => {
        const { startTime, endTime } = Billing.billingCycleToTimeRange(validBillingCycles.monthly);

        await service.create(job);

        expect(mockCustomerFindOne).toHaveBeenCalledWith({ customerId, businessID });
        expect(mockGenerateInvoiceForUsageTotal).toHaveBeenCalledWith({
            businessID,
            customerId,
            start: startTime,
            end: endTime,
        });
        expect(mockLoadPoints).toHaveBeenCalledTimes(1);
        const [bucket, org, points] = mockLoadPoints.mock.calls[0];
        expect(bucket).toEqual(`${process.env.STAGE}-aggregate-usage`);
        expect(org).toEqual('enterprise');
        expect(points).toHaveLength(1);
    });

    it('does not invoice a customer without an offering', async () => {
        mockCustomerFindOne.mockImplementation(() => ({ data: [{ customerId }], message: 'Found Customer' }));

        await service.create(job);

        expect(mockGenerateInvoiceForUsageTotal).not.toHaveBeenCalled();
        expect(mockLoadPoints).not.toHaveBeenCalled();
    });

    it('publishes an audit event when the billing report fails', async () => {
        const publishEvent = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
        mockGenerateInvoiceForUsageTotal.mockImplementationOnce(() => {
            throw new Error('invoice generation blew up');
        });

        await expect(service.create(job)).resolves.toBeUndefined();

        expect(publishEvent).toHaveBeenCalledWith(expect.objectContaining({ topic: AuditScope.ERROR }));
        expect(mockLoadPoints).not.toHaveBeenCalled();
        publishEvent.mockRestore();
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { getQueueToken } from '@nestjs/bull';
import { SchedulerService } from './scheduler.service';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from './dto/scheduler.dto';
import { billingScheduleConsumers } from '../billing/entities/billing.entity';
import { infrastructureType } from '../dimensions/dto/create-dimension.dto';

describe('SchedulerService', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'b9459f53-054b-4437-8ecd-b6f8070344fc';

    let service: SchedulerService;
    const mockQueueAdd = jest.fn();
    const mockBillingQueueAdd = jest.fn();

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [
                SchedulerService,
                { provide: getQueueToken('scheduler_queue'), useValue: { add: mockQueueAdd } },
                { provide: getQueueToken('scheduler_billing_queue'), useValue: { add: mockBillingQueueAdd } },
            ],
        }).compile();

        service = module.get<SchedulerService>(SchedulerService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    describe('emitOne', () => {
        it('emits billing jobs onto the billing queue with the billingReport consumer', async () => {
            await service.emitOne({
                schedulerId: customerId,
                payload: {
                    businessID,
                    schedulerStatus: SchedulerStatus.live,
                    schedulerType: schedulerType.billing,
                    scheduleParameters: { customerId, businessID },
                    rate: SupportedMeasurementFrequencies.monthly,
                },
            });

            expect(mockQueueAdd).not.toHaveBeenCalled();
            expect(mockBillingQueueAdd).toHaveBeenCalledWith(
                billingScheduleConsumers.billingReport,
                expect.objectContaining({
                    schedulerID: customerId,
                    businessID,
                    schedulerType: schedulerType.billing,
                    scheduleParameters: { customerId, businessID },
                })
            );
        });

        it('emits measurements onto the scheduler queue with the dimension consumer', async () => {
            await service.emitOne({
                schedulerId: 'scheduler-1',
                payload: {
                    businessID,
                    dimensionType: infrastructureType.ebsVolume,
                    schedulerStatus: SchedulerStatus.live,
                    schedulerType: schedulerType.dimensionDataGathering,
                    scheduleParameters: { dimensionType: infrastructureType.ebsVolume },
                    rate: SupportedMeasurementFrequencies.perMinute,
                },
            });

            expect(mockBillingQueueAdd).not.toHaveBeenCalled();
            expect(mockQueueAdd).toHaveBeenCalledWith(
                infrastructureType.ebsVolume,
                expect.objectContaining({ schedulerID: 'scheduler-1', businessID })
            );
        });
    });
});

